select json_build_object('types',(select coalesce(json_agg(json_build_object('name',t.typname,'kind',t.typtype,'labels',(select json_agg(e.enumlabel order by e.enumsortorder) from pg_enum e where e.enumtypid=t.oid))),'[]'::json) from pg_type t join pg_namespace n on n.oid=t.typnamespace where n.nspname='public' and t.typtype in ('e','d','c') and not exists (select 1 from pg_class c where c.reltype=t.oid)),'sequences',(select coalesce(json_agg(sequencename),'[]'::json) from pg_sequences where schemaname='public'),'event_triggers',(select coalesce(json_agg(evtname),'[]'::json) from pg_event_trigger),'publications',(select coalesce(json_agg(json_build_object('pub',pubname,'schema',schemaname,'table',tablename)),'[]'::json) from pg_publication_tables),'non_system_schemas',(select coalesce(json_agg(nspname order by nspname),'[]'::json) from pg_namespace where nspname !~ '^pg_' and nspname <> 'information_schema')) as data;
